static void need(bool x){if(!x)throw std::runtime_error("VFGP negative test failed");} static void p32(std::vector<uint8_t>&b,size_t at,uint32_t x){for(size_t i=0;i<4;++i)b[at+i]=uint8_t(x>>(24-8*i));} static void p64(std::vector<uint8_t>&b,size_t at,uint64_t x){p32(b,at,uint32_t(x>>32));p32(b,at+4,uint32_t(x));}
static std::vector<uint8_t> vfar(uint32_t w,uint32_t h,uint8_t m,std::vector<uint8_t> p){std::vector<uint8_t>b{'V','F','A','R',1,m,0,0};b.resize(24);p32(b,8,w);p32(b,12,h);p64(b,16,uint64_t(w)*h);b.insert(b.end(),p.begin(),p.end());return b;} static std::vector<uint8_t> v2(std::vector<uint8_t>a){std::vector<uint8_t>b{'V','F','G','P',2,0,0,0};b.resize(40);p32(b,8,40);p32(b,12,uint32_t(3+a.size()));p32(b,20,9);p32(b,24,2);p32(b,28,2);p32(b,32,3);p32(b,36,uint32_t(a.size()));b.insert(b.end(),{1,2,3});b.insert(b.end(),a.begin(),a.end());return b;} static void no(std::vector<uint8_t>b,size_t max=16u*1024u*1024u){Parser p(max);std::vector<Frame>f;need(!p.Push(b,&f)&&!p.Finish());}
int main()try{auto raw=v2(vfar(2,2,0,{1,2,3,4}));auto rle=v2(vfar(2,2,1,{0x83,9}));for(auto const*record:{&raw,&rle})for(size_t cut=1;cut<record->size();++cut){Parser p;std::vector<Frame>f;need(p.Push({record->data(),cut},&f)&&!p.Finish());}auto dims=raw;p32(dims,51,3);no(dims);auto declared=raw;p64(declared,59,3);no(declared);auto mode=raw;mode[48]=2;no(mode);auto reserved=raw;reserved[49]=1;no(reserved);auto version=raw;version[47]=2;no(version);auto raw_extra=raw;raw_extra.push_back(5);p32(raw_extra,36,29);p32(raw_extra,12,32);no(raw_extra);no(v2(vfar(2,2,1,{0x83})));no(v2(vfar(2,2,1,{0x84,7})));no(v2(vfar(2,2,1,{0x83,7,0})));auto outer=raw;outer[4]=3;no(outer);no(raw,raw.size()-1);Parser exact(raw.size());std::vector<Frame>f;need(exact.Push(raw,&f)&&exact.Finish()&&f.size()==1&&f[0].alpha==std::vector<uint8_t>{1,2,3,4});std::cout<<"PASS VFGP v2 bad dims/truncation/run overflow/trailing/version/limit\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
